<article class="task-card" :draggable="page==='projects'&&canWrite(projects.find(p=>p.id===t.project_id))" @dragstart.stop="if(page==='projects')beginTaskDrag(t)" @dragend="taskDrag=null" :class="{'is-complete':t.completed_at}"><div class="task-card-title"><button class="completion" :class="{'checked':t.completed_at}" :disabled="!canWrite(projects.find(p=>p.id===t.project_id))" @click.stop="toggleTask(t)" :aria-label="(t.completed_at?'باز کردن ':'تکمیل ')+t.title"><span x-show="t.completed_at" x-html="$icon('Check')"></span></button><button @click="openTask(t)" class="task-title" x-text="t.title"></button></div><div class="task-tags" x-show="t.labels.length"><template x-for="l in t.labels" :key="l.id"><span class="tag" :style="`--tag-color:${l.color}`"><i></i><span x-text="l.name"></span></span></template></div><div class="task-card-bottom"><span class="task-date" :class="{'overdue':overdue(t)}"><span x-html="$icon('CalendarDays')"></span><span x-text="date(t.due_date)"></span></span><span class="subtask-count" x-show="t.subtasks.length"><span x-html="$icon('CheckCheck')"></span><span x-text="subProgress(t)"></span></span><span class="avatar tiny" x-show="t.owner_id" :title="member(t.owner_id).name"><img x-show="member(t.owner_id).avatar_url" :src="member(t.owner_id).avatar_url" :alt="member(t.owner_id).name"><span x-show="!member(t.owner_id).avatar_url" :style="`background:${color(t.owner_id)}`" x-text="initials(member(t.owner_id).name)"></span></span></div></article>
